// Mock de @minecraft/server-ui: las respuestas se toman de una cola programable (ui.queue).
// Cada entrada puede ser: número (botón), texto (botón cuyo texto contiene ese texto, o valor de campo de texto),
// true/false (MessageForm), una función (form) => respuesta, o undefined (cerrar).
export const ui = { queue: [], shown: [] };
export const FormCancelationReason = { UserBusy: 'UserBusy', UserClosed: 'UserClosed' };
export const FormResponse = class {};

function respond(kind, form) {
  ui.shown.push({ kind, title: form._title, body: form._body, buttons: form._buttons, fields: form._fields });
  if (!ui.queue.length) return { canceled: true, cancelationReason: 'UserClosed' };
  const next = ui.queue.shift();
  if (next === undefined) return { canceled: true, cancelationReason: 'UserClosed' };
  return typeof next === 'function' ? next(form) : next;
}

export class ActionFormData {
  constructor() { this._buttons = []; }
  title(t) { this._title = t; return this; }
  body(b) { this._body = b; return this; }
  button(t) { this._buttons.push(t); return this; }
  label() { return this; }
  header() { return this; }
  divider() { return this; }
  async show() {
    const r = respond('action', this);
    if (typeof r === 'number') return { canceled: false, selection: r };
    if (typeof r === 'string') {
      const i = this._buttons.findIndex((b) => b.replace(/§./g, '').includes(r));
      return i >= 0 ? { canceled: false, selection: i } : { canceled: true, cancelationReason: 'UserClosed' };
    }
    return r;
  }
}

export class ModalFormData {
  constructor() { this._fields = []; }
  title(t) { this._title = t; return this; }
  textField(l) { this._fields.push(['text', l]); return this; }
  dropdown(l, items) { this._fields.push(['dropdown', l, items]); return this; }
  slider(l) { this._fields.push(['slider', l]); return this; }
  toggle(l) { this._fields.push(['toggle', l]); return this; }
  label() { return this; }
  header() { return this; }
  divider() { return this; }
  submitButton() { return this; }
  async show() {
    const r = respond('modal', this);
    if (typeof r === 'string' || typeof r === 'number' || typeof r === 'boolean') return { canceled: false, formValues: [r] };
    if (Array.isArray(r)) return { canceled: false, formValues: r };
    return r;
  }
}

export class MessageFormData {
  title(t) { this._title = t; return this; }
  body(b) { this._body = b; return this; }
  button1(t) { this._b1 = t; return this; }
  button2(t) { this._b2 = t; return this; }
  async show() {
    const r = respond('message', this);
    if (r === true) return { canceled: false, selection: 0 };
    if (r === false) return { canceled: false, selection: 1 };
    return r;
  }
}
